function pause(ms: number, signal: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    signal.throwIfAborted();
    const done = () => { signal.removeEventListener("abort", abort); resolve(); };
    const timer = setTimeout(done, ms);
    const abort = () => { clearTimeout(timer); signal.removeEventListener("abort", abort); reject(signal.reason); };
    signal.addEventListener("abort", abort, { once: true });
  });
}

async function jsonRequest(context: Context, path: string, signal: AbortSignal, init: RequestInit = {}) {
  const response = await context.tool.fetch(`http://127.0.0.1:8188${path}`, {
    ...init, signal: AbortSignal.any([signal, AbortSignal.timeout(60000)]),
  });
  if (!response.ok) throw new Error(`ComfyUI ${path.split("?")[0]}：HTTP ${response.status} ${context.tool.errorMessage(await response.text())}`);
  return await response.json();
}

function mediaSeconds(bytes: Uint8Array, mime: string) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const word = (start: number) => Buffer.from(bytes.subarray(start,start+4)).toString("ascii");
  if(mime === "audio/wav" || mime === "audio/x-wav") {
    if(word(0)!=="RIFF" || word(8)!=="WAVE") throw new Error("参考音频须为有效 WAV");
    let byteRate=0, dataSize=0;
    for(let pos=12;pos+8<=bytes.length;) {
      const size=view.getUint32(pos+4,true);
      if(word(pos)==="fmt " && size>=16 && pos+24<=bytes.length) byteRate=view.getUint32(pos+16,true);
      if(word(pos)==="data") dataSize+=Math.min(size,bytes.length-pos-8);
      pos+=8+size+(size%2);
    }
    if(!byteRate || !dataSize) throw new Error("无法读取 WAV 音频时长");
    return dataSize/byteRate;
  }
  if(mime === "video/mp4") {
    function find(start: number,end: number): number | undefined {
      for(let pos=start;pos+8<=end;) {
        let size=view.getUint32(pos), header=8;
        if(size===1) { if(pos+16>end) break; size=Number(view.getBigUint64(pos+8)); header=16; }
        if(size===0) size=end-pos;
        if(size<header || pos+size>end) break;
        const kind=word(pos+4), offset=pos+header;
        if(kind==="mvhd") {
          const version=view.getUint8(offset), scaleAt=offset+(version===1?20:12), durationAt=scaleAt+4;
          if(durationAt+(version===1?8:4)>pos+size) break;
          const scale=view.getUint32(scaleAt), ticks=version===1?Number(view.getBigUint64(durationAt)):view.getUint32(durationAt);
          if(scale && ticks) return ticks/scale;
        }
        if(kind==="moov") { const value=find(offset,pos+size); if(value!==undefined) return value; }
        pos+=size;
      }
    }
    const duration=find(0,bytes.length);
    if(duration!==undefined && Number.isFinite(duration)) return duration;
    throw new Error("无法读取 MP4 时长，请使用包含完整 moov 的 MP4");
  }
  return undefined;
}

async function upload(context: Context, input: MediaInput, family: string, signal: AbortSignal) {
  let bytes: Uint8Array;
  let mime = input.mimeType?.split(";")[0];
  if (input.type === "url") {
    const url = new URL(input.url);
    if (!["http:", "https:"].includes(url.protocol)) throw new Error("素材 URL 必须使用 HTTP(S)");
    const response = await context.tool.fetch(url, { signal: AbortSignal.any([signal, AbortSignal.timeout(120000)]) });
    if (!response.ok) throw new Error(`读取参考素材失败：HTTP ${response.status}`);
    mime ||= response.headers.get("content-type")?.split(";")[0];
    if (Number(response.headers.get("content-length")) > 100 * 1024 * 1024) throw new Error("单个素材不能超过 100MB");
    bytes = new Uint8Array(await response.arrayBuffer());
  } else if (input.type === "base64") {
    const match = /^data:([^;,]+);base64,([\s\S]+)$/.exec(input.data);
    mime = match?.[1] ?? mime;
    bytes = Buffer.from(match?.[2] ?? input.data, "base64");
  } else bytes = input.data;
  if (!bytes.length || bytes.length > 100 * 1024 * 1024) throw new Error("参考素材为空或超过 100MB");
  const extensions: Record<string, string> = { "image/png": "png", "image/jpeg": "jpg", "image/webp": "webp", "video/mp4": "mp4", "audio/wav": "wav", "audio/x-wav": "wav" };
  if (!mime || !mime.startsWith(`${family}/`) || !extensions[mime]) throw new Error(`不支持的 ${family} 素材格式：${mime ?? "未知 MIME"}`);
  const seconds=mediaSeconds(bytes,mime);
  if(seconds!==undefined && (seconds<2 || seconds>15.05)) throw new Error("参考视频或音频每段须为2–15秒");
  const boundary = `h3Local${Date.now()}${Math.floor(Math.random() * 1e9)}`;
  const filename = `${boundary}.${extensions[mime]}`;
  const body = Buffer.concat([
    Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="image"; filename="${filename}"\r\nContent-Type: ${mime}\r\n\r\n`),
    Buffer.from(bytes), Buffer.from(`\r\n--${boundary}\r\nContent-Disposition: form-data; name="type"\r\n\r\ninput\r\n--${boundary}--\r\n`),
  ]);
  const result = await jsonRequest(context, "/upload/image", signal, { method: "POST", headers: { "Content-Type": `multipart/form-data; boundary=${boundary}` }, body });
  if (!result.name || result.type !== "input") throw new Error("ComfyUI 未返回有效的上传文件");
  return {name:result.subfolder ? `${result.subfolder}/${result.name}` : result.name,seconds};
}

function formatPrompt(text: string, mode: string, frames: number, imageCount: number, videoCount: number, audioCount: number) {
  const duration = (frames / 24).toFixed(2);
  if (mode === "r2v") {
    if (text.includes("subject_definitions:")) {
      if(!["retention_analysis:","detailed_description:","overall_soundscape:","non_diegetic_music:","summary:"].every(field=>text.includes(field))) throw new Error("R2V结构化提示词需要完整六个字段");
      return text;
    }
    const sources = [
      ...Array.from({ length: imageCount }, (_, i) => `<Picture ${i + 1}> is reference image ${i + 1}`),
      ...Array.from({ length: videoCount }, (_, i) => `<Video ${i + 1}> provides motion and temporal structure`),
      ...Array.from({ length: audioCount }, (_, i) => `<Audio ${i + 1}> provides the standalone audio reference`),
    ];
    return `subject_definitions: ${sources.join("; ")}.\n\nsummary: Generate a ${duration}-second video following the description and references.\n\nretention_analysis: Preserve the appearance of reference subjects and follow the supplied motion and audio references where relevant.\n\ndetailed_description: [Shot 1] ${text}\n\noverall_soundscape: Natural synchronized sounds appropriate to the described scene.\n\nnon_diegetic_music: N/A`;
  }
  const shots = [...text.matchAll(/\[Shot (\d+)\]/g)];
  const finalShot = shots.length ? shots[shots.length - 1][1] : "1";
  let body = text;
  if (!body.includes("integrated_multimodal_description:")) body = `integrated_multimodal_description: [Shot 1] ${body}\n\noverall_soundscape: Natural synchronized sounds appropriate to the described scene.\n\nnon_diegetic_music: N/A`;
  else if (!body.includes("overall_soundscape:") || !body.includes("non_diegetic_music:")) throw new Error("H3 结构化提示词需要完整的三个字段");
  if (mode === "t2v" || /^(For the target video|How the reference pictures align)/.test(body)) return body;
  const instruction = mode === "i2v"
    ? "For the target video, at 0.00 seconds into the target video, <Picture 1> (from [Shot 1]) is fully referenced."
    : mode === "fl2v"
      ? `How the reference pictures align with the target video — Picture 1 (from Shot 1) aligns with the 0.00-second mark of the target video; Picture 2 (from Shot ${finalShot}) aligns with the ${duration}-second mark of the target video.`
      : `How the reference pictures align with the target video — <Picture 1> (from [Shot ${finalShot}]) aligns with the ${duration}-second mark of the target video.`;
  return `${instruction}\n\n${body}`;
}

export default {
  id: "h3Local3060",
  label: "本地 MiniMax H3 · RTX3060 五模式",
  version: "2.0.0",
  readme: "Powered by MiniMax H3。直连本机 ComfyUI http://127.0.0.1:8188，无 API Key。五模式：T2V、首帧 I2V、首尾 FL2V、尾帧 L2V、R2V。默认608×352、5秒请求（124帧/24fps≈5.17秒），FL2VA使用LightX2V Turbo8，Ref2VA使用Turbo4；使用本地32B INT8编码器、INT8 DiT、SageAttention和分块FFN。若安装官方32B NVFP4编码器则优先选择它。other.profile可选official（20步基线）、balanced（20步+CPU Block Cache）、sparse（20步+Sol-Attn）、turbo4、turbo8（仅FL2VA）；other.seed可固定种子。Turbo为近似蒸馏，低分辨率偏离训练画幅；768p可在ComfyUI手动尝试。R2V上限9图/3视频/3音频、总12文件，3060建议先用1图；图片支持PNG/JPEG/WebP，参考视频仅MP4，独立音频仅WAV，单片2–15秒，同类合计最多15秒；视频24fps重采样并由H3按目标长度裁取。视频原声默认不用，other.referenceVideoAudio=true可启用，此时须提供完整六段提示词，视频原声的Audio标签排在独立音频之前。音频不能单独作为参考。取消只取消本任务。所有视频均含原生声音；不支持添加水印。普通提示词只作格式封装，不含官方托管Context-IR或2K再生成。",
  rules: [],
  models: [
    { id: "h3T2v", label: "H3 文生视频", type: "video", mode: ["text"], audio: true, durationResolutionMap: [{ duration: [5, 8, 10, 15], resolution: ["352p", "480p", "544p"] }] },
    { id: "h3I2v", label: "H3 首帧图生视频", type: "video", mode: ["singleImage"], audio: true, durationResolutionMap: [{ duration: [5, 8, 10, 15], resolution: ["352p", "480p", "544p"] }] },
    { id: "h3Fl2v", label: "H3 首尾帧生视频", type: "video", mode: ["startEndRequired"], audio: true, durationResolutionMap: [{ duration: [5, 8, 10, 15], resolution: ["352p", "480p", "544p"] }] },
    { id: "h3L2v", label: "H3 尾帧生视频", type: "video", mode: ["startFrameOptional"], audio: true, durationResolutionMap: [{ duration: [5, 8, 10, 15], resolution: ["352p", "480p", "544p"] }] },
    { id: "h3R2v", label: "H3 参考生视频", type: "video", mode: [["imageReference:9", "videoReference:3", "audioReference:3"]], audio: true, durationResolutionMap: [{ duration: [5, 8, 10, 15], resolution: ["352p", "480p", "544p"] }] },
  ],
  async getPrice() { return { price: "本地算力", tips: "消耗本机显存、内存与电力，无远程生成接口费用" }; },
  async generateVideo(this: Context, request: VideoRequest): Promise<MediaAsset[]> {
    const modes: Record<string, string> = { h3T2v: "t2v", h3I2v: "i2v", h3Fl2v: "fl2v", h3L2v: "l2v", h3R2v: "r2v" };
    const mode = modes[request.model];
    if (!mode || !request.prompt?.trim()) throw new Error("模型无效或提示词为空");
    if (request.generateAudio === false || request.watermark === true) throw new Error("H3 联合生成原生音频；当前不支持关闭声音或添加水印");
    const other = request.other ?? {};
    if (Object.keys(other).some(key => !["profile", "seed", "referenceVideoAudio"].includes(key))) throw new Error("other 仅支持 profile、seed 和 referenceVideoAudio");
    if(other.referenceVideoAudio!==undefined && typeof other.referenceVideoAudio!=="boolean") throw new Error("referenceVideoAudio 必须为布尔值");
    if(other.referenceVideoAudio && (mode!=="r2v" || !request.prompt.includes("subject_definitions:"))) throw new Error("使用参考视频原声需选R2V并填写完整六段提示词；视频原声的<Audio N>标签排在独立音频之前");
    const profile = String(other.profile ?? (mode === "r2v" ? "turbo4" : "turbo8"));
    const template = workflowTemplates[`${mode}_${profile}`];
    if (!template) throw new Error("不支持的加速档位；Ref2VA 暂不提供 turbo8");
    const duration = request.duration ?? 5;
    if (![5, 8, 10, 15].includes(duration)) throw new Error("时长支持 5、8、10、15 秒，按 17k+5 帧网格向上取整");
    const sizes: Record<string, [number, number]> = { "352p": [608, 352], "480p": [864, 480], "544p": [960, 544] };
    const size = sizes[request.resolution ?? "352p"];
    const ratio = request.ratio ?? "16:9";
    if (!size || !["16:9", "9:16", "1:1", "4:3", "3:4"].includes(ratio)) throw new Error("分辨率支持352p/480p/544p；比例支持16:9、9:16、1:1、4:3、3:4");
    const [rw, rh] = ratio.split(":").map(Number);
    const short = size[1];
    const width = ratio==="16:9" ? size[0] : ratio==="9:16" ? size[1] : Math.round((rw >= rh ? short * rw / rh : short) / 32) * 32;
    const height = ratio==="16:9" ? size[1] : ratio==="9:16" ? size[0] : Math.round((rh >= rw ? short * rh / rw : short) / 32) * 32;
    const count = Math.round(duration * 24);
    const frames = count + (5 - count % 17 + 17) % 17;
    const seed = other.seed ?? Math.floor(Math.random() * 2147483647);
    if (!Number.isSafeInteger(seed) || Number(seed) < 0) throw new Error("seed 必须为非负安全整数");
    const images = request.images ?? [], videos = request.videos ?? [], audios = request.audios ?? [];
    let first = request.firstFrame, last = request.lastFrame;
    if (mode === "i2v" && images.length === 1 && !first) first = images[0];
    if (mode !== "r2v" && (videos.length || audios.length || images.length > (mode === "i2v" && !request.firstFrame ? 1 : 0))) throw new Error("此模式不接受额外参考素材，请使用 R2V");
    if (mode === "t2v" && (first || last)) throw new Error("文生视频不能提供首尾帧");
    if (mode === "i2v" && (!first || last)) throw new Error("I2V 需要一张首帧，不能提供尾帧");
    if (mode === "fl2v" && (!first || !last)) throw new Error("FL2V 需要首帧和尾帧");
    if (mode === "l2v" && (!last || first)) throw new Error("L2V 需要尾帧，并保持首帧为空");
    if (mode === "r2v" && (first || last || !images.length && !videos.length || images.length > 9 || videos.length > 3 || audios.length > 3 || images.length + videos.length + audios.length > 12)) throw new Error("R2V 需图片或视频参考，不接受首尾帧；上限9图/3视频/3音频，共12个文件");
    const expectedModes: Record<string,string> = {t2v:"text", i2v:"singleImage", fl2v:"startEndRequired", l2v:"startFrameOptional"};
    if (request.mode !== undefined && (mode === "r2v" ? !Array.isArray(request.mode) : request.mode !== expectedModes[mode])) throw new Error("请求模式与所选模型不匹配");
    const signal = AbortSignal.any([AbortSignal.timeout(4 * 60 * 60 * 1000), ...(this.signal ? [this.signal] : [])]);
    signal.throwIfAborted();
    const graph: Graph = JSON.parse(JSON.stringify(template));
    const condition = graph["5"].inputs;
    Object.assign(condition, {width, height, length:frames, prompt:formatPrompt(request.prompt.trim(), mode, frames, images.length, videos.length, audios.length)});
    graph["8"].inputs.noise_seed = seed;
    // Check installed nodes and exact filenames before uploading or queueing anything.
    const info = await jsonRequest(this, "/object_info", signal);
    const clipOptions=info.CLIPLoader?.input?.required?.clip_name?.[0]??[];
    if(clipOptions.includes("qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors")) graph["2"].inputs.clip_name="qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors";
    if(videos.length && !info.VHS_LoadVideo || audios.length && !info.LoadAudio) throw new Error("ComfyUI缺少参考视频或音频加载节点");
    for (const item of Object.values(graph)) {
      if (!info[item.class_type]) throw new Error(`ComfyUI 缺少节点：${item.class_type}`);
      for (const field of ["unet_name", "clip_name", "vae_name", "lora_name"]) {
        const filename = item.inputs[field];
        if (!filename) continue;
        const schema = info[item.class_type].input;
        const spec = schema.required?.[field] ?? schema.optional?.[field];
        const options = Array.isArray(spec?.[0]) ? spec[0] : spec?.[1]?.options;
        if (!options?.includes(filename)) throw new Error(`缺少模型 ${filename}；请先完成 h3Local 模型下载`);
      }
    }
    if (first) graph["15"].inputs.image = (await upload(this, first, "image", signal)).name;
    if (last) graph["16"].inputs.image = (await upload(this, last, "image", signal)).name;
    if (mode === "r2v") {
      delete graph["15"];
      delete condition["ref_images.ref_image_0"];
      for (let i=0; i<images.length; i++) {
        const id=String(100+i);
        graph[id]={class_type:"LoadImage",inputs:{image:(await upload(this, images[i], "image", signal)).name}};
        condition[`ref_images.ref_image_${i}`]=[id,0];
      }
      let videoSeconds=0, audioSeconds=0;
      for (let i=0; i<videos.length; i++) {
        const id=String(120+i);
        const uploaded=await upload(this,videos[i],"video",signal);
        videoSeconds+=uploaded.seconds??0;
        if(videoSeconds>15.05) throw new Error("参考视频总时长不能超过15秒");
        graph[id]={class_type:"VHS_LoadVideo",inputs:{video:uploaded.name,force_rate:24,custom_width:width,custom_height:height,frame_load_cap:360,skip_first_frames:0,select_every_nth:1,format:"None"}};
        condition[`ref_videos.ref_video_${i}`]=[id,0];
        if(other.referenceVideoAudio) condition[`ref_video_audios.ref_video_audio_${i}`]=[id,2];
      }
      for (let i=0; i<audios.length; i++) {
        const id=String(140+i);
        const uploaded=await upload(this,audios[i],"audio",signal);
        audioSeconds+=uploaded.seconds??0;
        if(audioSeconds>15.05) throw new Error("独立参考音频总时长不能超过15秒");
        graph[id]={class_type:"LoadAudio",inputs:{audio:uploaded.name}};
        condition[`ref_audios.ref_audio_${i}`]=[id,0];
      }
    }
    const result=await jsonRequest(this,"/prompt",signal,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({prompt:graph,client_id:`h3Local3060_${Date.now()}`})});
    const promptId=result.prompt_id;
    if (typeof promptId!=="string" || !/^[a-f0-9-]{36}$/i.test(promptId)) throw new Error("ComfyUI 未返回有效任务 ID");
    let completed=false;
    const cancel=()=>{ void this.queryFetch(`http://127.0.0.1:8188/api/jobs/${promptId}/cancel`,{method:"POST",signal:AbortSignal.timeout(10000)}).catch(()=>{}); };
    signal.addEventListener("abort",cancel,{once:true});
    if(signal.aborted) cancel();
    try {
      while(true) {
        signal.throwIfAborted();
        const history=await jsonRequest(this,`/history/${promptId}`,signal);
        const record=history[promptId];
        if(record) {
          if(record.status?.status_str==="error") throw new Error(`H3 生成失败：${this.tool.errorMessage(record.status.messages)}`);
          if(record.status?.completed) {
            completed=true;
            const output=record.outputs?.["14"];
            const video=[...(output?.images??[]),...(output?.videos??[]),...(output?.gifs??[])].find((v:any)=>/\.mp4$/i.test(v.filename??""));
            if(!video || video.type!=="output") throw new Error("生成已结束，但没有返回 MP4 视频");
            const query=new URLSearchParams({filename:video.filename,subfolder:video.subfolder??"",type:"output"});
            const response=await this.tool.fetch(`http://127.0.0.1:8188/view?${query}`,{signal:AbortSignal.any([signal,AbortSignal.timeout(120000)])});
            if(!response.ok) throw new Error(`读取视频失败：HTTP ${response.status}`);
            if(Number(response.headers.get("content-length"))>100*1024*1024) throw new Error("视频超过100MB");
            const bytes=new Uint8Array(await response.arrayBuffer());
            if(bytes.length<12 || bytes.length>100*1024*1024 || Buffer.from(bytes.subarray(4,8)).toString("ascii")!=="ftyp") throw new Error("返回的视频不是有效 MP4 或超过100MB");
            return [{mediaType:"video",type:"binary",data:bytes,mimeType:"video/mp4"}];
          }
        }
        await pause(2000,signal);
      }
    } finally {
      signal.removeEventListener("abort",cancel);
      if(!completed) cancel();
    }
  },
};
